#!/system/bin/sh
B="${0%/*}/bin/busybox"; F="$@"; [ -f "$F" ]||exit 1; base="${F##*/}"; dir="${F%$base}"; [ -n "$dir" ]||dir="./"; OUT="${dir}${base%.*}_MSAPatcher_LargeAPK.txt"; bytes="$($B stat -c %s "$F" 2>/dev/null)"; mb=$((bytes/1048576)); L="$($B unzip -qql "$F" 2>/dev/null)"; dex="$(echo "$L"|$B grep -E 'classes([0-9]*)?\.dex$'|$B wc -l|$B tr -d ' ')"; so="$(echo "$L"|$B grep -E 'lib/.+\.so$'|$B wc -l|$B tr -d ' ')"; mode=NORMAL; [ "$mb" -ge 300 ]&&mode=STREAMING; [ "$mb" -ge 1000 ]&&mode=LOW-MEMORY-STREAMING; { echo "MSAPatcher 6.2 - Large APK Readiness"; echo "APK: $base"; echo "Size: ${mb} MB (${bytes} bytes)"; echo "DEX files: $dex"; echo "Native libraries: $so"; echo "Recommended scan mode: $mode"; echo; echo "Largest ZIP entries:"; echo "$L"|$B sort -nr|$B head -n10; echo; echo "No full extraction was performed."; } > "$OUT"; cat "$OUT"